use quince_core::types::Trade;use quince_indicators::{CustomIndicator,CustomIndicatorError,CustomIndicatorRegistration,IndicatorDescriptor,IndicatorInput,IndicatorOutput,IndicatorParameter};static P:&[IndicatorParameter]=&[IndicatorParameter{name:"alpha",min:0.001,max:1.}];static D:IndicatorDescriptor=IndicatorDescriptor{name:"custom_ewma_volatility",input:IndicatorInput::Trade,output:IndicatorOutput::ScalarF64,parameters:P};pub static REGISTRATION:CustomIndicatorRegistration=CustomIndicatorRegistration{descriptor:&D,create};struct I{a:f64,last:Option<f64>,v:f64}fn create(x:&[f64])->Result<Box<dyn CustomIndicator>,CustomIndicatorError>{Ok(Box::new(I{a:x[0],last:None,v:0.}))}impl CustomIndicator for I{fn on_trade(&mut self,t:&Trade)->Option<f64>{let Some(p)=self.last else{self.last=Some(t.price);return None};let r=(t.price/p).ln();self.v=self.a*r*r+(1.-self.a)*self.v;self.last=Some(t.price);Some(self.v.sqrt())}}
#[cfg(test)]mod tests{use super::*;use chrono::Utc;use quince_core::types::Side;fn t(p:f64)->Trade{Trade{price:p,qty:1.,time:Utc::now(),side:Side::Buy,trade_id:1}}#[test]fn ewma(){let mut i=create(&[0.5]).unwrap();assert_eq!(i.on_trade(&t(1.)),None);assert!(i.on_trade(&t(2.)).unwrap()>0.);}}
